<button class="w-9 h-9 rounded-full bg-surface-container-low flex items-center justify-center text-outline hover:text-on-surface transition-colors" disabled="" type="button">
<span class="material-symbols-outlined text-base">chevron_left</span>
</button>
<button class="w-9 h-9 rounded-full bg-primary text-on-primary font-label-md text-label-md font-bold shadow-sm" type="button">1</button>
<button class="w-9 h-9 rounded-full bg-surface-container-low hover:bg-surface-container-high text-on-surface font-label-md text-label-md transition-colors" type="button">2</button>
<button class="w-9 h-9 rounded-full bg-surface-container-low hover:bg-surface-container-high text-on-surface font-label-md text-label-md transition-colors" type="button">3</button>
<button class="w-9 h-9 rounded-full bg-surface-container-low hover:bg-surface-container-high flex items-center justify-center text-on-surface transition-colors" type="button">
<span class="material-symbols-outlined text-base">chevron_right</span>
</button>
</div>
</div>
</div>
<!-- INTEGRATED QUICK AUDIT INSIGHT & NOTIFICATION BANNER -->
<div class="relative overflow-hidden bg-gradient-to-r from-emerald-600 via-teal-600 to-emerald-700 text-white p-space-lg rounded-[2rem] shadow-[0_16px_36px_-8px_rgba(5,150,105,0.4)] flex flex-col md:flex-row items-center justify-between gap-space-md"><div class="flex items-center gap-space-md relative z-10"><div class="w-14 h-14 rounded-2xl bg-white/20 backdrop-blur-md text-white border border-white/30 flex items-center justify-center shadow-lg shrink-0"><span class="material-symbols-outlined text-3xl">verified_user</span></div><div class="flex flex-col gap-1"><h3 class="font-headline-sm text-headline-sm text-white font-bold tracking-tight">Validasi Fisik Gudang Terjadwal Hari Ini</h3><p class="font-body-sm text-body-sm text-emerald-50 max-w-2xl leading-relaxed">Setiap penambahan stok otomatis dikompilasi ke kartu stok fisik bar. Pastikan paraf serah terima supplier terarsip rapi untuk audit berkala.</p></div></div><div class="flex items-center gap-space-sm shrink-0 relative z-10"><button class="px-space-md py-2.5 rounded-full bg-white/15 hover:bg-white/25 border border-white/25 font-label-md text-label-md text-white transition-all shadow-sm backdrop-blur-sm" type="button">Buka Berkas PO &amp; Faktur</button><button class="px-space-lg py-2.5 rounded-full bg-white text-emerald-800 hover:bg-emerald-50 font-label-md text-label-md font-bold shadow-[0_8px_16px_rgba(0,0,0,0.15)] hover:scale-105 active:scale-95 transition-all" type="button">Audit Stok Sekarang</button></div><div class="absolute -right-10 -bottom-10 w-48 h-48 rounded-full bg-white/10 blur-2xl pointer-events-none"></div><div class="absolute -left-10 -top-10 w-48 h-48 rounded-full bg-teal-400/20 blur-2xl pointer-events-none"></div></div>
<!-- MODAL DIALOG: FORM TAMBAH PENAMBAHAN STOK (+ Tambah Stok Bahan) -->
<div class="fixed inset-0 z-50 flex items-center justify-center p-4 bg-on-surface/40 backdrop-blur-md hidden transition-opacity" id="stockModal">
<div class="bg-surface-container-lowest w-full max-w-2xl rounded-[2.5rem] shadow-[0_24px_48px_-12px_rgba(0,108,73,0.25),0_12px_24px_-6px_rgba(16,24,40,0.1)] p-space-lg flex flex-col gap-space-md relative max-h-[90vh] overflow-y-auto">
<!-- Modal Header -->
<div class="flex items-start justify-between pb-space-xs border-b border-surface-variant/50">
<div class="flex items-center gap-space-sm">
<div class="w-11 h-11 rounded-2xl bg-secondary-container text-on-secondary-container flex items-center justify-center shadow-sm">
<span class="material-symbols-outlined text-2xl">inventory</span>
</div>
<div class="flex flex-col">
<h3 class="font-headline-sm text-headline-sm text-on-surface font-bold">Catat Penambahan Stok Bahan Masuk</h3>
<span class="font-body-sm text-body-sm text-on-surface-variant">Inventaris Warkop Cak Kebo • Shift Aktif</span>
</div>
</div>
<button class="w-9 h-9 rounded-full bg-surface-container-low hover:bg-surface-container-high flex items-center justify-center text-outline hover:text-on-surface transition-colors" id="closeStockModalBtn" type="button">
<span class="material-symbols-outlined text-lg">close</span>
</button>
</div>
<!-- Modal Body / Form -->
<form class="flex flex-col gap-space-md" id="addStockForm">
<!-- Grid Tanggal & Waktu -->
<div class="grid grid-cols-1 md:grid-cols-2 gap-space-md">
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Tanggal &amp; Waktu Masuk</label>
<div class="flex items-center bg-surface-container-low px-4 py-2.5 rounded-full shadow-inner">
<span class="material-symbols-outlined text-outline text-lg mr-2">event</span>
<input class="w-full bg-transparent font-body-sm text-body-sm text-on-surface focus:outline-none" type="text" value="10 Sep 2026 • 14:00 WIB">
</div>
</div>
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Petugas Penerima / PIC</label>
<div class="flex items-center bg-surface-container-low px-4 py-2.5 rounded-full shadow-inner">
<span class="material-symbols-outlined text-primary text-lg mr-2">badge</span>
<select class="w-full bg-transparent font-body-sm text-body-sm text-on-surface focus:outline-none cursor-pointer">
<option value="bima">Admin Bima (Bar Supervisor)</option>
<option value="alisa">Alisa Yasmin (Head Barista)</option>
<option value="iman">Iman Labibus (Floor Captain)</option>
<option value="rian">Rian Santoso (Dapur Warkop)</option>
</select>
</div>
</div>
</div>
<!-- Dropdown Pilih Jenis Bahan -->
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Pilih Komoditas / SKU Bahan Baku</label>
<div class="relative bg-surface-container-low rounded-2xl p-1 shadow-inner">
<select class="w-full py-2.5 pl-4 pr-10 bg-transparent font-body-md text-body-md text-on-surface focus:outline-none cursor-pointer appearance-none">
<option value="robusta">Biji Kopi Robusta Dampit Malang (SKU-KOP-001)</option>
<option value="arabica">Biji Kopi Arabica Ijen Honey (SKU-KOP-002)</option>
<option value="carnation">Susu Carnation Kental Manis 370g (SKU-DRY-004)</option>
<option value="freshmilk">Greenfields Fresh Milk Pasteurisasi 1L (SKU-DRY-001)</option>
<option value="gula">Gula Pasir Kristal Putih (SKU-GLA-003)</option>
<option value="sirup_pandan">Sirup Pandan Wangi Racik Kebo (SKU-SRP-005)</option>
<option value="cup16">Cup Dingin Sablon Cak Kebo 16oz (SKU-CUP-016)</option>
<option value="mie">Indomie Goreng Rasa Spesial (SKU-MIE-002)</option>
</select>
<span class="material-symbols-outlined text-outline pointer-events-none absolute right-4 top-3 text-xl">expand_more</span>
</div>
</div>
<!-- Kuantitas & Satuan -->
<div class="grid grid-cols-1 md:grid-cols-2 gap-space-md">
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Jumlah / Kuantitas Masuk</label>
<div class="flex items-center bg-surface-container-low px-4 py-2.5 rounded-full shadow-inner">
<span class="material-symbols-outlined text-secondary text-lg mr-2">add_circle_outline</span>
<input class="w-full bg-transparent font-body-sm text-body-sm text-on-surface focus:outline-none" min="1" placeholder="Contoh: 25" type="number">
</div>
</div>
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Satuan Logistik</label>
<div class="flex items-center bg-surface-container-low px-4 py-2.5 rounded-full shadow-inner">
<span class="material-symbols-outlined text-outline text-lg mr-2">straighten</span>
<select class="w-full bg-transparent font-body-sm text-body-sm text-on-surface focus:outline-none cursor-pointer">
<option value="kg">Kilogram (kg)</option>
<option value="karton">Karton / Dus</option>
<option value="sak">Sak / Karung</option>
<option value="pcs">Pieces (Pcs / Biji)</option>
<option value="liter">Liter (L)</option>
<option value="kaleng">Kaleng</option>
</select>
</div>
</div>
</div>
<!-- Total Pembelian & No Faktur -->
<div class="grid grid-cols-1 md:grid-cols-2 gap-space-md">
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Total Biaya Pembelian (Rp)</label>
<div class="flex items-center bg-surface-container-low px-4 py-2.5 rounded-full shadow-inner">
<span class="font-label-md text-label-md text-outline mr-2 font-bold">Rp</span>
<input class="w-full bg-transparent font-body-sm text-body-sm text-on-surface focus:outline-none" placeholder="Contoh: 1.850.000" type="text">
</div>
</div>
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">No. Faktur / Nota Pembelian</label>
<div class="flex items-center bg-surface-container-low px-4 py-2.5 rounded-full shadow-inner">
<span class="material-symbols-outlined text-outline text-lg mr-2">receipt_long</span>
<input class="w-full bg-transparent font-body-sm text-body-sm text-on-surface focus:outline-none" placeholder="Contoh: INV/2026/09/8812" type="text">
</div>
</div>
</div>
<!-- Catatan Operasional -->
<div class="flex flex-col gap-1.5">
<label class="font-label-md text-label-md text-on-surface font-semibold">Keterangan / Catatan Serah Terima</label>
<textarea class="w-full bg-surface-container-low p-3.5 rounded-2xl font-body-sm text-body-sm text-on-surface focus:outline-none shadow-inner resize-none" placeholder="Tuliskan catatan kondisi fisik kemasan, batch roastery, masa kadaluarsa, atau catatan khusus bar..." rows="3"></textarea>
</div>
<!-- Upload Foto Nota Fisik (Opsional) -->
<div class="p-3.5 rounded-2xl bg-surface-container-low flex items-center justify-between border-dashed border-2 border-outline-variant/60">
<div class="flex items-center gap-3">
<div class="w-10 h-10 rounded-full bg-surface-container-lowest flex items-center justify-center text-primary shadow-sm">
<span class="material-symbols-outlined text-xl">cloud_upload</span>
</div>
<div>
<span class="font-label-md text-label-md text-on-surface block font-bold">Unggah Bukti Nota / Foto Surat Jalan</span>
<span class="font-body-sm text-body-sm text-outline">Format JPG, PNG atau PDF maks 5MB</span>
</div>
</div>
<button class="px-3 py-1.5 rounded-full bg-surface-container-lowest text-on-surface hover:bg-surface-container-high font-label-badge text-label-badge font-bold shadow-sm" type="button">
            Pilih Berkas
          </button>
</div>
<!-- Action Buttons -->
<div class="flex items-center justify-end gap-space-sm pt-space-xs">
<button class="px-space-lg py-2.5 rounded-full bg-surface-container-low hover:bg-surface-container-high text-on-surface font-label-md text-label-md transition-all" id="cancelModalBtn" type="button">
            Batal
          </button>
<button class="flex items-center gap-2 px-space-xl py-2.5 rounded-full bg-secondary text-on-secondary font-label-lg text-label-lg shadow-[0_8px_20px_-4px_rgba(0,108,73,0.4)] hover:brightness-105 transition-all transform active:scale-95" id="saveStockBtn" type="button">
<span class="material-symbols-outlined text-xl">check</span>
<span class="">Simpan Catatan Stok</span>
</button>
</div>
</form>
</div>
</div>
<!-- INTERACTIVE TOAST POPUP (CLIENT-SIDE) -->
<div class="fixed bottom-6 right-6 z-50 transform translate-y-20 opacity-0 transition-all duration-300 pointer-events-none" id="toastNotification">
<div class="bg-inverse-surface text-inverse-on-surface px-space-md py-3 rounded-2xl shadow-xl flex items-center gap-3">
<span class="material-symbols-outlined text-secondary-fixed text-xl">check_circle</span>
<span class="font-label-md text-label-md" id="toastMessage">Stok bahan baku berhasil ditambahkan!</span>
</div>
</div>
</div>
<script>
  // DOM Elements
  const openModalBtn = document.getElementById('openStockModalBtn');
  const closeModalBtn = document.getElementById('closeStockModalBtn');
  const cancelModalBtn = document.getElementById('cancelModalBtn');
  const stockModal = document.getElementById('stockModal');
  const saveStockBtn = document.getElementById('saveStockBtn');
  const searchInput = document.getElementById('searchInput');
  const toastNotification = document.getElementById('toastNotification');
  const toastMessage = document.getElementById('toastMessage');

  // Modal open/close logic
  function showModal() {
    stockModal.classList.remove('hidden');
  }

  function hideModal() {
    stockModal.classList.add('hidden');
  }

  openModalBtn.addEventListener('click', showModal);
  closeModalBtn.addEventListener('click', hideModal);
  cancelModalBtn.addEventListener('click', hideModal);

  // Close when clicking modal backdrop
  stockModal.addEventListener('click', (e) => {
    if (e.target === stockModal) {
      hideModal();
    }
  });

  // Toast Helper
  function showToast(msg) {
    toastMessage.textContent = msg;
    toastNotification.classList.remove('translate-y-20', 'opacity-0');
    toastNotification.classList.add('translate-y-0', 'opacity-100');
    setTimeout(() => {
      toastNotification.classList.add('translate-y-20', 'opacity-0');
      toastNotification.classList.remove('translate-y-0', 'opacity-100');
    }, 3200);
  }

  // Save stock simulation
  saveStockBtn.addEventListener('click', () => {
    hideModal();
    showToast('Berhasil menyimpan catatan penambahan stok bahan!');
  });

  // Quick Client-Side Search Filtering
  searchInput.addEventListener('input', (e) => {
    const term = e.target.value.toLowerCase();
    const rows = document.querySelectorAll('#logTableBody tr');
    rows.forEach(row => {
      const text = row.innerText.toLowerCase();
      row.style.display = text.includes(term) ? '' : 'none';
    });
  });

  // Date Filter Switch active styles
  const filterBtns = document.querySelectorAll('.filter-date');
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => {
        b.classList.remove('bg-surface-container-lowest', 'text-primary', 'font-bold', 'shadow-sm');
        b.classList.add('text-on-surface-variant');
      });
      btn.classList.add('bg-surface-container-lowest', 'text-primary', 'font-bold', 'shadow-sm');
      btn.classList.remove('text-on-surface-variant');
      showToast(`Filter rentang tanggal diperbarui ke: ${btn.textContent.trim()}`);
    });
  });
</script></main></div>





</body></html>
